#[allow(dead_code, unused_parens)]
fn plural_category(family: Option<&str>, count: i64) -> &'static str {
    let n = count.unsigned_abs();
    let _ = n;
    match family {
        Some("en") => if n == 1 { "one" } else { "other" },
        _ => "other",
    }
}

